package com.taskflow.config;
import com.taskflow.model.*;import com.taskflow.repo.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.beans.factory.annotation.Value;import java.time.LocalDate;
@Configuration public class DemoData{
 @Bean CommandLineRunner seedDemo(@Value("${app.demo-seed:false}") boolean enabled,UserRepository users,ProjectRepository projects,TaskRepository tasks,PasswordEncoder encoder){return args->{if(!enabled||users.existsByEmailIgnoreCase("admin@taskflow.local"))return;AppUser admin=users.save(new AppUser("Alex Morgan","admin@taskflow.local",encoder.encode("TaskFlow2026!"),Role.ADMIN));AppUser jordan=users.save(new AppUser("Jordan Lee","jordan@taskflow.local",encoder.encode("TaskFlow2026!"),Role.MANAGER));AppUser sam=users.save(new AppUser("Sam Kim","sam@taskflow.local",encoder.encode("TaskFlow2026!"),Role.MEMBER));Project p=projects.save(new Project("Website redesign","A fresh, thoughtful experience for our customers.","#6457df",admin));p.members.add(jordan);p.members.add(sam);projects.save(p);tasks.save(new Task("Map the current user journey","Document key touchpoints and pain points.",Priority.HIGH,p,jordan,admin,LocalDate.now().plusDays(3)));Task t=tasks.save(new Task("Explore visual directions","Create three visual concepts for the landing page.",Priority.MEDIUM,p,sam,admin,LocalDate.now().plusDays(5)));t.status=TaskStatus.IN_PROGRESS;tasks.save(t);tasks.save(new Task("Review content inventory","Audit existing copy and identify what needs a refresh.",Priority.LOW,p,null,admin,LocalDate.now().plusDays(8)));};}
}
